WITH lines AS (SELECT id, created_at, coupon_codes, item.product_id, item.price, item.promo FROM (SELECT id, created_at, coupon_codes, EXPLODE_OUTER(items) AS item FROM carts) x) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, promo, SUM(CASE WHEN promo = 'WELCOME5' THEN product_id ELSE 0 END) AS welcome5_product_id, APPROX_PERCENTILE(product_id, ARRAY(0.25, 0.5, 0.75)) AS product_id_quartiles FROM lines GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), promo), (DATE_TRUNC('HOUR', created_at))) ORDER BY welcome5_product_id DESC NULLS LAST;
